//! Pre-compiled contract BOC hex constants for TOS staking pool contracts.
//!
//! All hex strings are compiled from TOS-adapted FunC source code using the
//! TOS FunC compiler (2026-04-13). Source code lives in:
//!   ~/tos/crypto/smartcont/{single-nominator-pool,nominator-pool,liquid-staking}/

/// Nominator Pool (multi-nominator) contract code BOC hex.
/// Source: ~/tos/crypto/smartcont/nominator-pool/pool.fc
pub const NOMINATOR_POOL_CODE: &str = "";

/// Liquid Staking Controller contract code BOC hex.
/// Source: ~/tos/crypto/smartcont/liquid-staking/controller.func
pub const LIQUID_CONTROLLER_CODE: &str = "";

/// Liquid Staking Pool contract code BOC hex.
/// Source: ~/tos/crypto/smartcont/liquid-staking/pool.func
pub const LIQUID_POOL_CODE: &str = "";

/// Deploy controller 0 message body BOC hex.
/// Source: ~/tos/crypto/smartcont/liquid-staking/deploy_controller0.boc
/// Sent to the liquid pool address with 1 TOS to deploy the even-slot controller.
pub const DEPLOY_CONTROLLER_0_BOC: &str =
    "b5ee9c72410101010012000020b27edcad000000000000000000000000c2ad946c";

/// Deploy controller 1 message body BOC hex.
/// Source: ~/tos/crypto/smartcont/liquid-staking/deploy_controller1.boc
/// Sent to the liquid pool address with 1 TOS to deploy the odd-slot controller.
pub const DEPLOY_CONTROLLER_1_BOC: &str =
    "b5ee9c72410101010012000020b27edcad000000000000000000000001c12eff9e";
